"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  BAND_PRICE_AVERAGES,
  COUNTRY_AWARDS,
  GLOBAL_PROCEEDS,
  HEADLINE,
  SOURCE_NOTE,
  SOURCES,
  auctionOnly,
  fmtB,
  fmtMhzPop,
  fmtPct,
  obligationCoverageBuckets,
  priceCoverageQuadrants,
  topByPrice,
  type CountryAwardRow,
  type Region,
} from "@/data/global-5g-auction-proceeds-vs-coverage-2026-data";

// viz-types: price-coverage scatter, proceeds area, top-price bars, obligation composed, quadrant bars, band averages | layout: default

type ViewId =
  | "scatter"
  | "topprice"
  | "proceeds"
  | "obligations"
  | "quadrants"
  | "bands";

type DesignFilter = "auction-hybrid" | "all";

const CYAN = "#22d3ee";
const AMBER = "#fbbf24";
const ROSE = "#fb7185";
const EMERALD = "#34d399";
const VIOLET = "#a78bfa";
const SLATE = "#94a3b8";
const INDIGO = "#818cf8";

const REGION_COLORS: Record<Region, string> = {
  "North America": CYAN,
  Europe: VIOLET,
  "Asia-Pacific": EMERALD,
  "Latin America": AMBER,
  "Middle East": ROSE,
  Africa: INDIGO,
};

const ALL_REGIONS: Region[] = [
  "North America",
  "Europe",
  "Asia-Pacific",
  "Latin America",
  "Middle East",
  "Africa",
];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? (
          <p className="mt-1 text-sm text-slate-500">{subtitle}</p>
        ) : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-2.5 py-1.5 text-xs font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function filterRows(
  design: DesignFilter,
  regions: Set<Region>,
): CountryAwardRow[] {
  const base = design === "all" ? COUNTRY_AWARDS : auctionOnly();
  return base.filter((r) => regions.has(r.region));
}

export function Global5gAuctionProceedsVsCoverage2026Dashboard() {
  const [view, setView] = useState<ViewId>("scatter");
  const [design, setDesign] = useState<DesignFilter>("auction-hybrid");
  const [regions, setRegions] = useState<Set<Region>>(() => new Set(ALL_REGIONS));
  const [logPrice, setLogPrice] = useState(false);

  const rows = useMemo(
    () => filterRows(design, regions),
    [design, regions],
  );

  const scatterData = useMemo(
    () =>
      rows
        .filter((r) => r.usdPerMhzPop > 0 || r.design === "admin")
        .map((r) => ({
          ...r,
          x: r.usdPerMhzPop,
          y: r.coveragePct,
          z: Math.max(r.proceedsUsdB, 0.2) * 40,
          fill: REGION_COLORS[r.region],
        })),
    [rows],
  );

