function filterRows(
  design: DesignFilter,
  regions: Set<Region>,
): CountryAwardRow[] {
  const base = design === "all" ? COUNTRY_AWARDS : auctionOnly();
  return base.filter((r) => regions.has(r.region));
}

export function Global5gAuctionProceedsVsCoverage2026Dashboard() {
  const [view, setView] = useState<ViewId>("scatter");
