  const rows = useMemo(
    () => filterRows(design, regions),
    [design, regions],
  );

  const scatterData = useMemo(
    () =>
      rows
        .filter((r) => r.usdPerMhzPop > 0 || r.design === "admin")
        .map((r) => ({
          ...r,
          x: r.usdPerMhzPop,
          y: r.coveragePct,
