  const quadrants = useMemo(
    () => priceCoverageQuadrants(rows.filter((r) => r.design !== "admin" && r.usdPerMhzPop > 0)),
    [rows],
  );
  const obligations = useMemo(
    () => obligationCoverageBuckets(rows.filter((r) => r.design !== "admin")),
    [rows],
